                                                                                                                                                                                                                                                                                                                        // 3. FUNÇÃO: BUSCAR MENTOR POR ID
                                                                                                                                                                                                                                                                                                                        function buscarMentor(id) {
                                                                                                                                                                                                                                                                                                                            return mentores.find(mentor => mentor.id === id);
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                            // 4. FUNÇÃO: LISTAR TODOS OS MENTORES
                                                                                                                                                                                                                                                                                                                            function listarMentores() {
                                                                                                                                                                                                                                                                                                                                console.log('=== MENTORES DISPONÍVEIS ===');
                                                                                                                                                                                                                                                                                                                                    mentores.forEach(mentor => {
                                                                                                                                                                                                                                                                                                                                            console.log(`
                                                                                                                                                                                                                                                                                                                                                    Nome: ${mentor.nome}
                                                                                                                                                                                                                                                                                                                                                            Especialidade: ${mentor.especialidade}
                                                                                                                                                                                                                                                                                                                                                                    Email: ${mentor.email}
                                                                                                                                                                                                                                                                                                                                                                            Disponibilidade: ${mentor.disponibilidade}
                                                                                                                                                                                                                                                                                                                                                                                    ---`);
                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                        // 5. FUNÇÃO: LISTAR CURSOS
                                                                                                                                                                                                                                                                                                                                                                                        function listarCursos() {
                                                                                                                                                                                                                                                                                                                                                                                            console.log('=== CURSOS DISPONÍVEIS ===');
                                                                                                                                                                                                                                                                                                                                                                                                cursos.forEach(curso => {
                                                                                                                                                                                                                                                                                                                                                                                                        console.log(`
                                                                                                                                                                                                                                                                                                                                                                                                                ${curso.titulo}
                                                                                                                                                                                                                                                                                                                                                                                                                        Nível: ${curso.nivel}
                                                                                                                                                                                                                                                                                                                                                                                                                                Duração: ${curso.duracao}
                                                                                                                                                                                                                                                                                                                                                                                                                                        Progresso: ${curso.progresso}%
                                                                                                                                                                                                                                                                                                                                                                                                                                                ---`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 6. FUNÇÃO: CALCULAR PROGRESSO GERAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                    function calcularProgressoGeral() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const totalProgresso = cursos.reduce((acc, curso) => acc + curso.progresso, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            const mediaProgresso = totalProgresso / cursos.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Math.round(mediaProgresso);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 7. FUNÇÃO: AGENDAR MENTORIA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                function agendarMentoria(mentorId, data, hora) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const mentor = buscarMentor(mentorId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (mentor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sucesso: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mensagem: `Mentoria agendada com ${mentor.nome} em ${data} às ${hora}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mentor: mentor.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                data: data,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            hora: hora
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sucesso: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagem: 'Mentor não encontrado'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 8. FUNÇÃO: FILTRAR CURSOS POR NÍVEL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function filtrarCursosPorNivel(nivel) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return cursos.filter(curso => curso.nivel === nivel);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 9. FUNÇÃO: ATUALIZAR PROGRESSO DO CURSO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function atualizarProgresso(cursoId, novoProgresso) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const curso = cursos.find(c => c.id === cursoId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (curso) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    curso.progresso = Math.min(novoProgresso, 100);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sucesso: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem: `Progresso de "${curso.titulo}" atualizado para ${curso.progresso}%`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sucesso: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem: 'Curso não encontrado'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 10. FUNÇÃO: GERAR CERTIFICADO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function gerarCertificado(nomeAluno, cursoId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const curso = cursos.find(c => c.id === cursoId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (curso && curso.progresso === 100) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sucesso: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                certificado: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                aluno: nomeAluno,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                curso: curso.titulo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                dataEmissao: new Date().toLocaleDateString('pt-BR'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                codigoVerificacao: Math.random().toString(36).substr(2, 9).toUpperCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sucesso: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagem: 'Curso não concluído ainda'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 11. FUNÇÃO: ENVIAR MENSAGEM PARA MENTOR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function enviarMensagem(mentorId, mensagem) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const mentor = buscarMentor(mentorId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (mentor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sucesso: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mensagem: `Mensagem enviada para ${mentor.nome}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    timestamp: new Date().toLocaleTimeString('pt-BR')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sucesso: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem: 'Mentor não encontrado'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 12. FUNÇÃO: OBTER ESTATÍSTICAS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function obterEstatisticas() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    totalMentores: mentores.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            totalCursos: cursos.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    progressoGeral: calcularProgressoGeral() + '%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cursosCompletos: cursos.filter(c => c.progresso === 100).length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cursosEmProgresso: cursos.filter(c => c.progresso > 0 && c.progresso < 100).length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cursosNaoIniciados: cursos.filter(c => c.progresso === 0).length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ============================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // EXEMPLOS DE USO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ============================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Listar todos os mentores
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarMentores();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Listar todos os cursos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarCursos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Buscar um mentor específico
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('Mentor encontrado:', buscarMentor(1));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Agendar uma mentoria
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(agendarMentoria(1, '2026-02-15', '14:30'));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Filtrar cursos por nível
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('Cursos Iniciante:', filtrarCursosPorNivel('Iniciante'));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Atualizar progresso
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(atualizarProgresso(1, 100));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Gerar certificado
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(gerarCertificado('João Silva', 1));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Enviar mensagem
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(enviarMensagem(2, 'Olá, gostaria de tirar dúvidas sobre Full Stack'));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Obter estatísticas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('Estatísticas:', obterEstatisticas());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Calcular progresso geral
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('Progresso Geral:', calcularProgressoGeral() + '%');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                